def retry_fibonacci(n, max_attempts=3, delay=1):
    import time
    for attempt in range(max_attempts):
        try:
            if n < 0:
                raise ValueError("n must be non-negative")
            a, b = 0, 1
            for _ in range(n):
                a, b = b, a + b
            return a
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            time.sleep(delay)

def memoized_is_prime(n):
    if n < 2:
        return False
    cache = {}
    if n in cache:
        return cache[n]
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            cache[n] = False
            return False
    cache[n] = True
    return True
